namespace sv_0ee0adc0b50f493789b620295042fae6.Services;

public class AppointmentService
{
    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(new List<string>
        {
            "Dr. Smith",
            "Dr. Johnson",
            "Dr. Williams",
            "Dr. Brown",
            "Dr. Davis"
        });
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateTime date)
    {
        return Task.FromResult(new List<string>
        {
            "9:00 AM",
            "10:00 AM",
            "11:00 AM",
            "1:00 PM",
            "2:00 PM",
            "3:00 PM",
            "4:00 PM"
        });
    }

    /// <summary>
    /// Validates patient info and appointment selection against server-side rules.
    /// Returns a dictionary of field name -> error message for any validation failures.
    /// </summary>
    public Task<Dictionary<string, string>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, string>();

        // Reject patients with outstanding balance
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors["Email"] = "Account has outstanding balance";
        }

        // Reject self-pay patients for doctors who don't accept them
        if (insuranceProvider == "None" && doctor == "Dr. Smith")
        {
            errors["Doctor"] = "Selected doctor does not accept self-pay patients";
        }

        // Simulate race condition on time slot
        if (timeSlot == "10:00 AM")
        {
            errors["TimeSlot"] = "This slot is no longer available";
        }

        return Task.FromResult(errors);
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_0ee0adc0b50f493789b620295042fae6.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h1>Book an Appointment</h1>

<EditForm Model="@Model" OnValidSubmit="HandleSubmit" FormName="bookAppointment">
    <DataAnnotationsValidator />

    <h3>Step 1: Patient Information</h3>

    <div class="mb-3">
        <label class="form-label" for="patientName">Patient Name</label>
        <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
        <ValidationMessage For="@(() => Model.PatientName)" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="email">Email</label>
        <InputText id="email" class="form-control" @bind-Value="Model.Email" />
        <ValidationMessage For="@(() => Model.Email)" />
        @if (!string.IsNullOrEmpty(_serverErrors.GetValueOrDefault("Email")))
        {
            <div class="validation-message">@_serverErrors["Email"]</div>
        }
    </div>

    <div class="mb-3">
        <label class="form-label" for="phone">Phone</label>
        <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
        <ValidationMessage For="@(() => Model.Phone)" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="insurance">Insurance Provider</label>
        <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
            <option value="">-- Select --</option>
            <option value="Aetna">Aetna</option>
            <option value="BlueCross">BlueCross</option>
            <option value="Cigna">Cigna</option>
            <option value="UnitedHealth">UnitedHealth</option>
            <option value="None">None</option>
        </InputSelect>
        <ValidationMessage For="@(() => Model.InsuranceProvider)" />
    </div>

    @if (!_showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">Next</button>
    }

    @if (_showStep2)
    {
        <hr />
        <h3>Step 2: Appointment Details</h3>

        <div class="mb-3">
            <label class="form-label" for="doctor">Preferred Doctor</label>
            <InputSelect id="doctor" class="form-select" @bind-Value="Model.Doctor"
                         @bind-Value:after="OnDoctorOrDateChanged">
                <option value="">-- Select --</option>
                @foreach (var doc in _doctors)
                {
                    <option value="@doc">@doc</option>
                }
            </InputSelect>
            <ValidationMessage For="@(() => Model.Doctor)" />
            @if (!string.IsNullOrEmpty(_serverErrors.GetValueOrDefault("Doctor")))
            {
                <div class="validation-message">@_serverErrors["Doctor"]</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="date">Date</label>
            <InputDate id="date" class="form-control" @bind-Value="Model.AppointmentDate"
                       @bind-Value:after="OnDoctorOrDateChanged" />
            <ValidationMessage For="@(() => Model.AppointmentDate)" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="timeSlot">Time Slot</label>
            <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
                <option value="">-- Select --</option>
                @foreach (var slot in _timeSlots)
                {
                    <option value="@slot">@slot</option>
                }
            </InputSelect>
            <ValidationMessage For="@(() => Model.TimeSlot)" />
            @if (!string.IsNullOrEmpty(_serverErrors.GetValueOrDefault("TimeSlot")))
            {
                <div class="validation-message">@_serverErrors["TimeSlot"]</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="reason">Reason for Visit</label>
            <InputTextArea id="reason" class="form-control" @bind-Value="Model.ReasonForVisit" rows="3" />
            <ValidationMessage For="@(() => Model.ReasonForVisit)" />
        </div>

        <button type="button" class="btn btn-secondary me-2" @onclick="CheckAvailability">
            Check Availability
        </button>
        <button type="submit" class="btn btn-success" disabled="@(!_validated)">
            Book Appointment
        </button>

        @if (_validated)
        {
            <div class="alert alert-success mt-3">Appointment is available! Click "Book Appointment" to confirm.</div>
        }
    }
</EditForm>

@if (_booked)
{
    <div class="alert alert-info mt-3">
        <strong>Appointment booked successfully!</strong> A confirmation will be sent to @Model.Email.
    </div>
}

@code {
    private AppointmentModel Model { get; set; } = new();
    private bool _showStep2;
    private bool _validated;
    private bool _booked;
    private List<string> _doctors = new();
    private List<string> _timeSlots = new();
    private Dictionary<string, string> _serverErrors = new();

    protected override async Task OnInitializedAsync()
    {
        _doctors = await AppointmentService.GetDoctorsAsync();
    }

    private async Task ProceedToStep2()
    {
        _serverErrors.Clear();

        // Manual step-1 validation
        if (string.IsNullOrWhiteSpace(Model.PatientName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            !IsValidEmail(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.InsuranceProvider))
        {
            return;
        }

        _showStep2 = true;
        _validated = false;
    }

    private async Task OnDoctorOrDateChanged()
    {
        _validated = false;
        _serverErrors.Remove("Doctor");
        _serverErrors.Remove("TimeSlot");

        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate != default)
        {
            _timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                Model.Doctor, Model.AppointmentDate);
            Model.TimeSlot = string.Empty;
        }
    }

    private async Task CheckAvailability()
    {
        _serverErrors.Clear();
        _validated = false;

        // Client-side step 2 validation
        if (string.IsNullOrWhiteSpace(Model.Doctor) ||
            Model.AppointmentDate == default ||
            Model.AppointmentDate <= DateTime.Today ||
            string.IsNullOrWhiteSpace(Model.TimeSlot) ||
            string.IsNullOrWhiteSpace(Model.ReasonForVisit) ||
            Model.ReasonForVisit.Length > 500)
        {
            return;
        }

        var errors = await AppointmentService.ValidatePatientAsync(
            Model.Email,
            Model.InsuranceProvider,
            Model.Doctor,
            Model.TimeSlot);

        if (errors.Count > 0)
        {
            _serverErrors = errors;
            return;
        }

        _validated = true;
    }

    private void HandleSubmit()
    {
        if (_validated)
        {
            _booked = true;
        }
    }

    private static bool IsValidEmail(string email)
    {
        try
        {
            var addr = new System.Net.Mail.MailAddress(email);
            return addr.Address == email;
        }
        catch
        {
            return false;
        }
    }
}

using System.ComponentModel.DataAnnotations;

namespace sv_0ee0adc0b50f493789b620295042fae6.Models;

public class AppointmentModel
{
    [Required(ErrorMessage = "Patient name is required")]
    public string PatientName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Email is required")]
    [EmailAddress(ErrorMessage = "Invalid email format")]
    public string Email { get; set; } = string.Empty;

    [Required(ErrorMessage = "Phone is required")]
    public string Phone { get; set; } = string.Empty;

    [Required(ErrorMessage = "Insurance provider is required")]
    public string InsuranceProvider { get; set; } = string.Empty;

    [Required(ErrorMessage = "Doctor is required")]
    public string Doctor { get; set; } = string.Empty;

    [Required(ErrorMessage = "Date is required")]
    [FutureDate(ErrorMessage = "Date must be in the future")]
    public DateTime AppointmentDate { get; set; }

    [Required(ErrorMessage = "Time slot is required")]
    public string TimeSlot { get; set; } = string.Empty;

    [Required(ErrorMessage = "Reason for visit is required")]
    [MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer")]
    public string ReasonForVisit { get; set; } = string.Empty;
}

public class FutureDateAttribute : ValidationAttribute
{
    public override bool IsValid(object? value)
    {
        if (value is DateTime date)
        {
            return date > DateTime.Today;
        }
        return false;
    }
}

